import{_ as n,l as i,o as e,c as l,v as r,p as s,x as t,d as p,i as d,S as E}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"债务积压","description":"","frontmatter":{"title":"债务积压","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/debt-overhang.md","filePath":"econ/debt-overhang.md","lastUpdated":1789023840000}'),c={name:"econ/debt-overhang.md"};function h(A,a,B,_,m,u){const o=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=r('<h1 id="债务积压" tabindex="-1">债务积压 <a class="header-anchor" href="#债务积压" aria-label="Permalink to &quot;债务积压&quot;">​</a></h1><div class="epigraph"><p>杠杆高到新投资的收益先填债权人的缺口时，股东会放弃正 NPV 项目；借债容量因此被自己的存量债卡住。</p><footer>—— Myers, Determinants of Corporate Borrowing, Journal of Financial Economics, 1977</footer></div><p><a href="/econ/bankruptcy-direct-indirect">上一课</a>把权衡右边拆成直接程序费用与间接经营激励，并点名 Myers 的投资不足。本课缺口是把那一条写成机制：存量风险债如何对增量项目征税。不重估律师费，不把优序提前。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>间接成本若只是「客户走了」，还缺少一张企业内部的决策图。Myers（1977）给出：企业是增长期权的组合。已有的风险债对期权的执行拥有优先索取。股东（或代表股东的经理）选择是否投入新股权去行使期权；若行权后的增值大部分落到债的安全上，股东的净现值为负，即使项目对整个企业是正 NPV。这就是债务积压。</p><p>缺口因此不是再证明直接成本小，而是：权衡里「事前间接」的一条具体技术——投资不足——如何从优先级里长出来。资产替代（赌大的）是下一课的相反扭曲；本课先钉放弃好项目。</p><p><span class="marginnote">积压：存量债像对增量投资的税。税率为债权人从该项目里拿走的份额。无风险债或可在行权前重新谈判到第一最佳时，税率为零。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把企业价值写成在位资产加增长期权。在位债面值足够高时，坏状态下在位资产不够偿债，期权的行权等于为债权人打工。股东的行权条件严于社会的 NPV 条件。事前，债的定价已经把积压写进利率，于是最优杠杆低于「只有税盾和律师费」的那个 \\(D^\\ast\\)。</p>',9)),(e(),s(E,null,{default:t(()=>[d(o,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20OPT%5B%22%E5%A2%9E%E9%95%BF%E6%9C%9F%E6%9D%83%22%5D%20--%3E%20NPV%5B%22%E9%A1%B9%E7%9B%AE%E5%AF%B9%E4%BC%81%E4%B8%9A%E4%B8%BA%E6%AD%A3%22%5D%0A%20%20DEBT%5B%22%E5%AD%98%E9%87%8F%E9%A3%8E%E9%99%A9%E5%80%BA%22%5D%20--%3E%20TAX%5B%22%E5%A2%9E%E5%80%BC%E5%85%88%E5%A1%AB%E5%80%BA%22%5D%0A%20%20TAX%20--%3E%20PASS%5B%22%E8%82%A1%E4%B8%9C%E6%94%BE%E5%BC%83%E8%A1%8C%E6%9D%83%22%5D%0A%20%20NPV%20--%3E%20PASS%0A%20%20PASS%20--%3E%20V%5B%22%E4%BA%8B%E5%89%8D%E4%BC%81%E4%B8%9A%E4%BB%B7%E5%80%BC%E4%B8%8B%E9%99%8D%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>重新谈判、缩短期限、约定保护性条款、或发行可转债，都是减轻积压的合同补丁。本课只标明：积压来自优先级，不是来自「经理懒」。下一课的风险转移是同一优先级下的另一方向。</p><h3 id="财务困境不是经济困境" tabindex="-1">财务困境不是经济困境 <a class="header-anchor" href="#财务困境不是经济困境" aria-label="Permalink to &quot;财务困境不是经济困境&quot;">​</a></h3><p>项目可以在全股权下该做。积压说的是资本结构让它不该做。上一课 Andrade–Kaplan 的过滤器在此落地：财务杠杆单独改变投资规则。不要把衰退里没人要的产品叫成 Myers 积压。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是剩余索取与控制权在行权时刻的错位。股东有限责任，上行归己、下行丢给债；但<strong>行权要先掏新钱</strong>时，有限责任帮不上忙——新钱是股权的，收益却被债截走。于是股权像被征税的看涨期权，税收来自存量债。债权人若能强迫行权，积压减轻，却要有控制权；那是后课治理，本课只从投资规则引入。</p><p>与火线出售的对照：火线出售是资产市场的买家约束；积压是企业内部的行权激励。两者都可以在杠杆高时同时出现：缺新股权不去投资，已有资产被迫贱卖。</p><p><span class="marginnote">Myers 1977 的对象是公司债与增长期权，不是主权债重组的全部政治。主权债务积压是同构比喻，机制课仍用企业优先级来写清。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要用「有债就会投资不足」覆盖所有杠杆：安全债、短期债、或投资由内部现金流完成时，积压弱。也不要把柠檬发股折价算进本课——那是优序，再后一课。下一课 <a href="/econ/risk-shifting">风险转移</a>把同一看涨期权翻过来：不放弃项目，而是把项目变得更险。</p><p>后课默认：存量风险债可以对增长期权征税，正 NPV 可以被股东拒绝。权衡右边的间接项至少包含这一条。</p><p>直接破产成本仍往往太小；积压是事前就会发生的间接项，不必等到立案。</p><p>缩短期限让债在期权到期前滚动，债权人可以拒绝展期来强迫再谈判，积压减轻，滚动危机加重——后课流动性会再写。本课只要：期限是积压的约束，不是把 Myers 删掉。</p><p>主权债、银行资本不足的「少放贷」，与企业增长期权同构，对象从项目换成信贷供给。机制仍是优先级对增量的税。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>债务积压：增量投资的收益被存量债截走，股东放弃正 NPV。</li><li>优先级制造对行权的税；安全债或有效重组可以关掉这条税。</li><li>这是间接困境成本的投资不足技术，不是律师费。</li><li>下一课把同一看涨期权翻过来：不放弃项目，而是把项目变得更险。</li><li>期限缩短减轻积压，但把滚动危机留给流动性课。</li><li>出处：Myers, <em>JFE</em> 1977。</li></ul>',15))])}const b=n(c,[["render",h]]);export{P as __pageData,b as default};
